import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int[] parentArray;
    static int totalComponents;

    static int findRoot(int x) {
        if (parentArray[x] == x) return x;
        parentArray[x] = findRoot(parentArray[x]);
        return parentArray[x];
    }

    static void unionSets(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return;
        totalComponents--;
        parentArray[b] = a;
    }

    static long powerMod(long base, int exponent) {
        if (exponent == 0) return 1;
        long halfPow = powerMod(base, exponent / 2);
        long res = (halfPow * halfPow) % MOD;
        if ((exponent & 1) == 1) res = (res * base) % MOD;
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();

        if (k == 0) {
            System.out.println(powerMod(p, (int)(p - 1)));
            return;
        }

        parentArray = new int[(int)p];
        totalComponents = (int)(p - (k > 1 ? 1 : 0));
        for (int i = 1; i < p; i++) {
            parentArray[i] = i;
        }

        for (int i = 1; i < p; i++) {
            unionSets(i, (int)((i * k) % p));
        }

        System.out.println(powerMod(p, totalComponents));
        scanner.close();
    }
}
